import { Math as PhaserMath, Scene, Time } from 'phaser';

import { IMPERIAL_HEAT_REGISTRY_KEY, GAME_REGISTRY, type GameRegistry } from '../data/GameRegistry';
import {
    eventBus,
    EVENT_CLIENT_MURDERED,
    EVENT_FIGHT_STARTED,
    EVENT_FIGHT_STOPPED,
    EVENT_HEAT_UPDATED,
    EVENT_IMPERIAL_RAID,
    type ClientMurderedData,
    type FightStartedData,
    type FightStoppedData,
    type HeatUpdatedData,
    type ImperialRaidData,
} from '../utils/EventBus';
/** Tracks Imperial attention generated by violent incidents in the cantina. */
export class ThreatManager {
    private heat: number;
    private activeFights = 0;
    private raidTriggered = false;
    private readonly heatTimer: Time.TimerEvent;

    private readonly handleClientMurdered = (_data: ClientMurderedData): void => {
        this.changeHeat(this.registry.threat.heatPerMurder);
    };

    private readonly handleFightStarted = (_data: FightStartedData): void => {
        this.activeFights++;
    };

    private readonly handleFightStopped = (_data: FightStoppedData): void => {
        this.activeFights = Math.max(0, this.activeFights - 1);
    };

    private readonly updateHeat = (): void => {
        if (this.raidTriggered) return;
        const change = this.activeFights > 0
            ? this.registry.threat.heatPerSecondFighting
            : -this.registry.threat.heatDecayPerSecond;
        this.changeHeat(change);
    };

    public constructor(
        private readonly scene: Scene,
        private readonly registry: GameRegistry = GAME_REGISTRY,
    ) {
        const storedHeat = this.scene.registry.get(IMPERIAL_HEAT_REGISTRY_KEY);
        this.heat = PhaserMath.Clamp(
            typeof storedHeat === 'number' ? storedHeat : this.registry.threat.startingHeat,
            0,
            this.registry.threat.maxHeat,
        );
        this.scene.registry.set(IMPERIAL_HEAT_REGISTRY_KEY, this.heat);
        eventBus.on(EVENT_CLIENT_MURDERED, this.handleClientMurdered);
        eventBus.on(EVENT_FIGHT_STARTED, this.handleFightStarted);
        eventBus.on(EVENT_FIGHT_STOPPED, this.handleFightStopped);
        this.heatTimer = this.scene.time.addEvent({
            delay: 1_000,
            loop: true,
            callback: this.updateHeat,
        });
    }

    public destroy(): void {
        eventBus.off(EVENT_CLIENT_MURDERED, this.handleClientMurdered);
        eventBus.off(EVENT_FIGHT_STARTED, this.handleFightStarted);
        eventBus.off(EVENT_FIGHT_STOPPED, this.handleFightStopped);
        this.heatTimer.remove(false);
    }

    public get currentHeat(): number {
        return this.heat;
    }

    private changeHeat(delta: number): void {
        if (this.raidTriggered || delta === 0) return;
        const previousHeat = this.heat;
        this.heat = PhaserMath.Clamp(
            this.heat + delta,
            0,
            this.registry.threat.maxHeat,
        );
        this.scene.registry.set(IMPERIAL_HEAT_REGISTRY_KEY, this.heat);
        const data: HeatUpdatedData = {
            currentHeat: this.heat,
            addedHeat: this.heat - previousHeat,
        };
        eventBus.emit(EVENT_HEAT_UPDATED, data);
        if (this.heat >= this.registry.threat.maxHeat) {
            this.raidTriggered = true;
            const raidData: ImperialRaidData = { heat: this.heat };
            eventBus.emit(EVENT_IMPERIAL_RAID, raidData);
        }
    }
}
